# Win-stay/lose-shift: observed vs generated by fitted ORL
source("scripts/04_orl.R")
results_orl <- readRDS("output/orl_fit_horstmann.rds")
deck_outcomes <- list(net_h[choice_h == 1], net_h[choice_h == 2],
                     net_h[choice_h == 3], net_h[choice_h == 4])

# WSLS for one sequence: P(stay | gain) - P(stay | loss)
wsls_of <- function(choice, outcome) {
  n <- length(choice)
  stay <- choice[-1] == choice[-n]
  gain <- outcome[-n] >= 0
  mean(stay[gain]) - mean(stay[!gain])
}

# Observed
wsls_obs <- rep(NA, nrow(choice_h))
for (i in 1:nrow(choice_h)) wsls_obs[i] <- wsls_of(choice_h[i, ], net_h[i, ])

# Generated: 20 simulations per person from their fitted ORL parameters
est <- as.matrix(results_orl[, c("Arew", "Apun", "Kprime", "betaF", "betaP")])
wsls_sim <- rep(NA, nrow(est))
set.seed(2026)
for (i in 1:nrow(est)) {
  vals <- rep(NA, 20)
  for (r in 1:20) {
    s <- sim_orl(est[i, ], deck_outcomes)
    vals[r] <- wsls_of(s$choice, s$outcome)
  }
  wsls_sim[i] <- mean(vals, na.rm = TRUE)
}

summary(wsls_obs)
summary(wsls_sim)
cor(wsls_obs, wsls_sim, use = "complete.obs")

# Same check for VPP (its perseverance depends on outcome)
source("scripts/03_vpp.R")
results_vpp <- readRDS("output/vpp_fit_horstmann.rds")
est_vpp <- as.matrix(results_vpp[, c("A", "alpha", "cons", "lambda",
                                     "epP", "epN", "K", "w")])
wsls_sim_vpp <- rep(NA, nrow(est_vpp))
set.seed(2026)
for (i in 1:nrow(est_vpp)) {
  vals <- rep(NA, 20)
  for (r in 1:20) {
    s <- sim_vpp(est_vpp[i, ], deck_outcomes)
    vals[r] <- wsls_of(s$choice, s$outcome)
  }
  wsls_sim_vpp[i] <- mean(vals, na.rm = TRUE)
}
summary(wsls_sim_vpp)
cor(wsls_obs, wsls_sim_vpp, use = "complete.obs")

# Observed vs. Simulated wsls
# (output/figures/wsls_observed_vs_simulated.png)

dir.create("output/figures", showWarnings = FALSE)
lims <- range(c(wsls_obs, wsls_sim, wsls_sim_vpp), na.rm = TRUE)

png("output/figures/wsls_observed_vs_simulated.png", width = 2000, height = 1000, res = 200)
par(mfrow = c(1,2))

plot(wsls_obs, wsls_sim, xlim = lims, ylim = lims, pch = 16, col = rgb(0,0,0,0.4),
     xlab = "Observed WSLS", ylab = "Simulated WSLS", main = "ORL")
abline(0,1,lty=2)

plot(wsls_obs, wsls_sim_vpp, xlim = lims, ylim = lims, pch = 16, col = rgb(0,0,0,0.4),
     xlab = "Observed WSLS", ylab = "Simulated WSLS", main = "VPP")
abline(0,1, lty =2)

dev.off()

# Paired t-test for ORL & VPP (t(161) = 7.2 & 1.06)
t.test(wsls_obs, wsls_sim, paired = TRUE)
mean(wsls_obs > wsls_sim, na.rm = TRUE)
t.test(wsls_obs, wsls_sim_vpp, paired = TRUE)
mean(wsls_obs > wsls_sim_vpp, na.rm = TRUE)













